export const searchSimilar = async (id: string,
    params: SearchSimilarParams, options?: RequestInit): Promise<searchSimilarResponse> => {
  
  return customFetch<searchSimilarResponse>(getSearchSimilarUrl(id,params),
  {      
    ...options,
    method: 'GET'
    
    
  }
);}





export const getSearchSimilarInfiniteQueryKey = (id: string,
    params?: SearchSimilarParams,) => {
    return [
    'infinite', `/api/search/similar/${id}`, ...(params ? [params] : [])
    ] as const;
    }

export const getSearchSimilarQueryKey = (id: string,
    params?: SearchSimilarParams,) => {
    return [
    `/api/search/similar/${id}`, ...(params ? [params] : [])
    ] as const;
    }

    
export const getSearchSimilarInfiniteQueryOptions = <TData = InfiniteData<Awaited<ReturnType<typeof searchSimilar>>>, TError = unknown>(id: string,
    params: SearchSimilarParams, options?: { query?:Partial<UseInfiniteQueryOptions<Awaited<ReturnType<typeof searchSimilar>>, TError, TData>>, request?: SecondParameter<typeof customFetch>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getSearchSimilarInfiniteQueryKey(id,params);

  

    const queryFn: QueryFunction<Awaited<ReturnType<typeof searchSimilar>>> = ({ signal }) => searchSimilar(id,params, { signal, ...requestOptions });

      

      

   return  { queryKey, queryFn, enabled: !!(id), ...queryOptions} as UseInfiniteQueryOptions<Awaited<ReturnType<typeof searchSimilar>>, TError, TData> & { queryKey: DataTag<QueryKey, TData, TError> }
}

